export const MAP_SIZE: Record<MapView, [number, number]> = { africa: [1000, 1000], west: [1600, 900], mali: [1000, 900] };

const FITS: Record<MapView, { lon0: number; lat1: number; cos: number; k: number; ox: number; oy: number }> = {"africa":{"lon0":-18.5,"lat1":38.5,"cos":0.999657,"k":13.5135,"ox":20.43,"oy":0},"west":{"lon0":-18.5,"lat1":27.5,"cos":0.96363,"k":37.5,"ox":14.04,"oy":0},"mali":{"lon0":-12.6,"lat1":25.3,"cos":0.953191,"k":58.4416,"ox":20.93,"oy":0}};

export function project(lon: number, lat: number, view: MapView): [number, number] {
  const f = FITS[view];
  return [Math.round(((lon - f.lon0) * f.cos * f.k + f.ox) * 10) / 10, Math.round(((f.lat1 - lat) * f.k + f.oy) * 10) / 10];
}

